const fn = new Function(code + "\nreturn { pick };");
const { pick } = fn();
const out = pick({ a: 1, b: 2, c: 3 }, ["a", "c"]);
if (out.a !== 1 || out.c !== 3 || "b" in out) throw new Error("pick({ a: 1, b: 2, c: 3 }, [\"a\", \"c\"]) should be exactly { a: 1, c: 3 }.");

const fn = new Function(code + "\nreturn { pick };");
const { pick } = fn();
const out = pick({ a: 1 }, ["a", "z"]);
if (out.a !== 1 || "z" in out) throw new Error("Keys that do not exist on the object must be skipped, not added as undefined.");

const fn = new Function(code + "\nreturn { pick };");
const { pick } = fn();
const input = { a: 1, b: 2 };
const out = pick(input, ["a"]);
if (out === input) throw new Error("pick must return a NEW object, not the input.");
if (input.b !== 2 || Object.keys(input).length !== 2) throw new Error("The input object must stay unchanged.");
